def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Determine the underlying storage
    if hasattr(self, "_items"):
        items = self._items
    else:
        items = self

    # Helper to get all values
    def all_values():
        if isinstance(items, dict):
            return list(items.values())
        # Assume iterable of values or list of (key, value) tuples
        if isinstance(items, (list, tuple)):
            # If items are tuples, return the second element
            if items and isinstance(items[0], tuple) and len(items[0]) == 2:
                return [v for _, v in items]
            return list(items)
        # Fallback: try to iterate
        return list(items)

    # If no keys specified, return all values
    if not keys:
        return all_values()

    result = []
    for key in keys:
        if isinstance(key, int):
            # Treat as index
            values = all_values()
            try:
                result.append(values[key])
            except IndexError:
                raise IndexError(f"Index {key} out of range.")
        else:
            # Treat as key
            if isinstance(items, dict):
                if key in items:
                    result.append(items[key])
                else:
                    raise KeyError(f"Key {key} not found.")
            else:
                # Assume list of (key, value) tuples
                found = False
                for k, v in items:
                    if k == key:
                        result.append(v)
                        found = True
                        break
                if not found:
                    raise KeyError(f"Key {key} not found.")
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # If no specific keys are requested, return all fields
    if not keys:
        return {k: v for k, v in zip(self._keys, self._values)}

    result = {}
    for key in keys:
        # Handle integer indices
        if isinstance(key, int):
            if key < 0 or key >= len(self._values):
                raise IndexError(f"Index {key} out of bounds")
            result[self._keys[key]] = self._values[key]
        else:
            # Handle string keys
            if isinstance(self._keys, dict):
                idx = self._keys.get(key)
                if idx is None:
                    result[key] = None
                    continue
            else:
                if key in self._keys:
                    idx = self._keys.index(key)
                else:
                    result[key] = None
                    continue
            # Ensure the index is within bounds
            if idx < 0 or idx >= len(self._values):
                raise IndexError(f"Index {idx} for key '{key}' out of bounds")
            result[key] = self._values[idx]
    return result

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Build the namespace for the new class
    namespace = {}
    # Store the SRID mapping on the class
    namespace['_srid_map'] = srid_map

    # Define an __init__ that accepts positional or keyword arguments for the fields
    def __init__(self, *args, **kwargs):
        # Call the base Point constructor (if it expects arguments, adjust accordingly)
        super(self.__class__, self).__init__()
        # Assign values to the specified fields
        for i, field in enumerate(fields):
            if i < len(args):
                setattr(self, field, args[i])
            else:
                setattr(self, field, kwargs.get(field))

    namespace['__init__'] = __init__

    # Provide a helpful __repr__ that shows the field values
    def __repr__(self):
        field_str = ', '.join(f'{f}={getattr(self, f)!r}' for f in fields)
        return f'{name}({field_str})'

    namespace['__repr__'] = __repr__

    # Create and return the new subclass of Point
    return type(name, (Point,), namespace)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

