def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        if cache is None:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
        elif lock is None:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(*args, **kwargs):
                k = key(*args, **kwargs)
                try:
                    with lock:
                        return cache[k]
                except KeyError:
                    pass  # key not found
                v = func(*args, **kwargs)
                try:
                    with lock:
                        cache[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, func)
    return decorator

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        usage = []

        def make_key(args, kwargs):
            if typed:
                key = tuple((arg, type(arg)) for arg in args)
                kw = tuple((k, v, type(v)) for k, v in sorted(kwargs.items()))
                return key + kw
            else:
                return args + tuple(sorted(kwargs.items()))

        def wrapper(*args, **kwargs):
            key = make_key(args, kwargs)
            if key in cache:
                # Move key to end to mark as most recent
                usage.remove(key)
                usage.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            usage.append(key)
            if maxsize and len(cache) > maxsize:
                # Evict most recent
                evict_key = usage.pop()
                del cache[evict_key]
            return result

        return wrapper
    return decorator

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.
    """
    def decorator(func):
        try:
            import functools
            return functools.lru_cache(maxsize=maxsize, typed=typed)(func)
        except AttributeError:
            import functools
            from collections import OrderedDict

            if maxsize == 0:
                @functools.wraps(func)
                def wrapper(*args, **kwargs):
                    return func(*args, **kwargs)
                return wrapper

            if maxsize is None:
                cache = {}
                @functools.wraps(func)
                def wrapper(*args, **kwargs):
                    key = (args, tuple(sorted(kwargs.items())))
                    if typed:
                        key = (tuple((type(a), a) for a in args),
                               tuple((k, type(v), v) for k, v in sorted(kwargs.items())))
                    if key in cache:
                        return cache[key]
                    result = func(*args, **kwargs)
                    cache[key] = result
                    return result
                return wrapper

            cache = OrderedDict()
            @functools.wraps(func)
            def wrapper(*args, **kwargs):
                key = (args, tuple(sorted(kwargs.items())))
                if typed:
                    key = (tuple((type(a), a) for a in args),
                           tuple((k, type(v), v) for k, v in sorted(kwargs.items())))
                if key in cache:
                    cache.move_to_end(key)
                    return cache[key]
                result = func(*args, **kwargs)
                cache[key] = result
                if len(cache) > maxsize:
                    cache.popitem(last=False)
                return result
            return wrapper
    return decorator

def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}

        def _make_key(args, kwargs, typed):
            key = args
            if kwargs:
                key += tuple(sorted(kwargs.items()))
            if typed:
                key = tuple((arg, type(arg)) for arg in args) + \
                      tuple(sorted((k, v, type(v)) for k, v in kwargs.items()))
            return key

        @wraps(func)
        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                value, count = cache[key]
                cache[key] = (value, count + 1)
                return value
            value = func(*args, **kwargs)
            if len(cache) >= maxsize:
                # Evict the least frequently used item
                min_key = None
                min_count = None
                for k, (_, c) in cache.items():
                    if min_count is None or c < min_count:
                        min_count = c
                        min_key = k
                if min_key is not None:
                    del cache[min_key]
            cache[key] = (value, 1)
            return value

        return wrapper

    return decorator

