def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if not classes:
        return []
    result = []
    for c in classes:
        if not isinstance(c, type):
            raise TypeError(f"Expected class type, got {type(c).__name__}")
        # Skip duplicates
        if c in result:
            continue
        # Skip if c is a subclass of any other class in the original list
        if any(c is not d and issubclass(c, d) for d in classes):
            continue
        result.append(c)
    return result

def namesAndDescriptions(self, all=False): # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    result = []
    classes = [self.__class__]
    if all:
        classes = self.__class__.__mro__
    for cls in classes:
        for name, value in cls.__dict__.items():
            if name.startswith('_'):
                continue
            if callable(value):
                continue
            description = getattr(value, '__doc__', None)
            if description is None:
                description = str(value)
            result.append((name, description))
    seen = set()
    unique = []
    for name, desc in result:
        if name not in seen:
            seen.add(name)
            unique.append((name, desc))
    return unique

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    names = set()
    classes = self.__class__.__mro__ if all else (self.__class__,)
    for cls in classes:
        # Class attributes that are not private and not callable
        for name, value in cls.__dict__.items():
            if not name.startswith('_') and not callable(value):
                names.add(name)
        # Include attributes defined via __slots__
        slots = getattr(cls, "__slots__", ())
        if isinstance(slots, str):
            slots = (slots,)
        for slot in slots:
            if not slot.startswith('_'):
                names.add(slot)
    return sorted(names)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
            _normalizeargs(v, output)

    return output

