def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    messages = []

    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({str(key): 'expected string or bytes-like object'})
        else:
            # Validate key regex
            if not LABEL_KEY_REGEX.match(key):
                messages.append(
                    {key: f"Label key '{key}' does not match the regex [...]"}
                )

        # Validate value type
        if not isinstance(value, (str, bytes)):
            messages.append({str(value): 'expected string or bytes-like object'})
        else:
            # Validate value regex
            if not LABEL_VALUE_REGEX.match(value):
                messages.append(
                    {value: f"Label value '{value}' does not match the regex [...]"}
                )

    if messages:
        raise ValidationError(messages)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Ensure the application has a spec and manifest
    if not hasattr(app, 'spec') or not hasattr(app.spec, 'manifest'):
        return
    # Prepare a dictionary to hold default schemas
    default_schemas = {}
    # Iterate over each resource in the manifest
    for resource in app.spec.manifest:
        # Skip if resource is not a dict
        if not isinstance(resource, dict):
            continue
        kind = resource.get('kind')
        metadata = resource.get('metadata', {})
        name = metadata.get('name')
        if not kind or not name:
            continue
        # Check if a custom observer schema already exists for this resource
        custom_schema = None
        if hasattr(app.spec, 'observers'):
            custom_schema = app.spec.observers.get(name)
        if custom_schema:
            continue
        # Build a simple default observer schema
        default_schema = {
            'kind': kind,
            'metadata': {'name': name},
            'spec': {}
        }
        default_schemas[name] = default_schema
    # Merge the default schemas into the application's observers
    if hasattr(app.spec, 'observers') and isinstance(app.spec.observers, dict):
        app.spec.observers.update(default_schemas)
    else:
        # If observers attribute does not exist, create it
        app.spec.observers = default_schemas
    return default_schemas

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    # Basic sanity checks
    if not path:
        return False

    # Resolve to a filesystem path if possible
    try:
        # If path is a pyfs object, try to get its root path
        if hasattr(path, 'root'):
            path = path.root
    except Exception:
        pass

    # Ensure path is a directory
    if not os.path.isdir(path):
        return False

    # Check for required OCFL metadata files
    ocfl_version_file = os.path.join(path, '.ocfl_version')
    if not os.path.isfile(ocfl_version_file):
        return False

    # Validate the contents of .ocfl_version (should be a number)
    try:
        with open(ocfl_version_file, 'r', encoding='utf-8') as f:
            content = f.read().strip()
        int(content)  # will raise ValueError if not an integer
    except Exception:
        return False

    # Optional: check for .ocfl_root file if present
    ocfl_root_file = os.path.join(path, '.ocfl_root')
    if os.path.isfile(ocfl_root_file):
        try:
            with open(ocfl_root_file, 'r', encoding='utf-8') as f:
                root_path = f.read().strip()
            # Resolve relative to the object root
            full_root = os.path.normpath(os.path.join(path, root_path))
            if not os.path.isdir(full_root):
                return False
        except Exception:
            return False

    # If all checks pass, consider the object valid
    return True

