def validate(self, inventory, extract_spec_version=False):
    """Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    if not isinstance(inventory, dict):
        raise ValueError("Inventory must be a dictionary")

    if extract_spec_version:
        type_val = inventory.get('type')
        if type_val is not None:
            try:
                self._validate_type(type_val, 'type')
                if isinstance(type_val, str) and type_val in getattr(self, 'allowed_spec_versions', []):
                    self.spec_version = type_val
            except Exception:
                # keep existing spec_version if type is invalid
                pass

    # Basic required fields for any spec
    required_fields = {'name', 'type'}
    missing = required_fields - inventory.keys()
    if missing:
        raise ValueError(f"Missing required fields: {missing}")

    # Additional validation based on spec_version
    if self.spec_version == 'v1':
        # v1 requires 'items'
        if 'items' not in inventory:
            raise ValueError("Missing 'items' for spec v1")
    elif self.spec_version == 'v2':
        # v2 requires 'components'
        if 'components' not in inventory:
            raise ValueError("Missing 'components' for spec v2")

    return inventory

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Ensure every digest referenced in the manifest is present in the set of used digests
    missing_files = [fname for fname, digest in manifest_files.items() if digest not in digests_used]
    if missing_files:
        raise ValueError(
            f"Digests for the following files are not used: {', '.join(missing_files)}"
        )

    # Ensure that no digest is used that is not present in the manifest
    manifest_digests = set(manifest_files.values())
    unused_digests = digests_used - manifest_digests
    if unused_digests:
        raise ValueError(
            f"Used digests that are not present in the manifest: {', '.join(unused_digests)}"
        )

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is the same type of validator
    if not isinstance(prior, type(self)):
        raise TypeError('prior must be an InventoryValidator instance')

    # Species must be a subset of current inventory species
    missing_species = set(prior.species) - set(self.species)
    if missing_species:
        raise ValueError(f'Prior contains species not in current inventory: {missing_species}')

    # Parameters must be a subset of current inventory parameters
    missing_params = set(prior.parameters) - set(self.parameters)
    if missing_params:
        raise ValueError(f'Prior contains parameters not in current inventory: {missing_params}')

    # Stoichiometry matrix: check that the submatrix for prior species matches
    # the corresponding rows in the current matrix (all reactions assumed in same order)
    try:
        species_index_map = {s: i for i, s in enumerate(self.species)}
        prior_species_indices = [species_index_map[s] for s in prior.species]
        # Compare row by row
        for idx, s in enumerate(prior.species):
            current_row = self.stoichiometry_matrix[species_index_map[s], :]
            prior_row = prior.stoichiometry_matrix[idx, :]
            if current_row != prior_row:
                raise ValueError(f'Stoichiometry row mismatch for species {s}')
    except Exception as exc:
        # If any attribute is missing or comparison fails, raise a clear error
        raise ValueError(f'Error validating stoichiometry matrix: {exc}')

    # Propensities: each prior propensity must exist in the current inventory
    for row in prior.propensities:
        if row not in self.propensities:
            raise ValueError(f'Prior propensity {row!r} not found in current inventory')

    # Constraints: each prior constraint must exist in the current inventory
    for c in prior.constraints:
        if c not in self.constraints:
            raise ValueError(f'Prior constraint {c!r} not found in current inventory')

    # Priors: each prior prior must exist in the current inventory
    for p in prior.priors:
        if p not in self.priors:
            raise ValueError(f'Prior prior {p!r} not found in current inventory')

    # If all checks pass, the prior is considered a valid prior version
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    result = {}

    def add_cf(logical_path, cf):
        result.setdefault(logical_path, set()).add(cf)

    def version_ge(v1, v2):
        """Return True if v1 >= v2 using simple numeric comparison."""
        try:
            # split on non-digit separators and compare tuples of ints
            parts1 = [int(p) if p.isdigit() else p for p in v1.replace('-', '.').split('.')]
            parts2 = [int(p) if p.isdigit() else p for p in v2.replace('-', '.').split('.')]
            # compare element-wise
            for a, b in zip(parts1, parts2):
                if a == b:
                    continue
                return a > b
            return len(parts1) >= len(parts2)
        except Exception:
            # fallback to string comparison
            return v1 >= v2

    if isinstance(inventory, dict):
        for logical_path, mapping in inventory.items():
            if isinstance(mapping, dict):
                for v, cf in mapping.items():
                    if version_ge(v, version):
                        add_cf(logical_path, cf)
            else:
                # assume mapping is an iterable of (version, content_file)
                for v, cf in mapping:
                    if version_ge(v, version):
                        add_cf(logical_path, cf)
    else:
        # assume inventory is an iterable of (logical_path, version, content_file)
        for entry in inventory:
            if len(entry) == 3:
                logical_path, v, cf = entry
                if version_ge(v, version):
                    add_cf(logical_path, cf)

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' must be a list")
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dictionary")
        if 'path' not in entry:
            raise ValueError("File entry missing required 'path' key")
        path = entry['path']
        if path not in manifest_files:
            raise ValueError(f"File '{path}' referenced in fixity not present in manifest")

def files_list(path):
    """Return the files in `path`"""
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    if os.path.isdir(path):
        return [
            os.path.abspath(os.path.join(path, f))
            for f in os.listdir(path)
            if os.path.isfile(os.path.join(path, f))
        ]
    return []

