def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = ' ' * indent

    def _pretty(obj, level):
        # Handle dictionaries
        if isinstance(obj, dict):
            if not obj:
                return '{}'
            items = []
            for k, v in obj.items():
                key_repr = _pretty(k, level + 1)
                val_repr = _pretty(v, level + 1)
                items.append(f'{key_repr}: {val_repr}')
            inner = ',\n'.join(' ' * ((level + 1) * 2) + item for item in items)
            return '{\n' + inner + '\n' + ' ' * (level * 2) + '}'

        # Handle lists, tuples, and sets
        if isinstance(obj, (list, tuple, set)):
            if not obj:
                if isinstance(obj, list):
                    return '[]'
                if isinstance(obj, tuple):
                    return '()'
                return 'set()'
            items = [_pretty(v, level + 1) for v in obj]
            inner = ',\n'.join(' ' * ((level + 1) * 2) + item for item in items)
            if isinstance(obj, list):
                return '[\n' + inner + '\n' + ' ' * (level * 2) + ']'
            if isinstance(obj, tuple):
                return '(\n' + inner + '\n' + ' ' * (level * 2) + ')'
            # set
            return 'set([\n' + inner + '\n' + ' ' * (level * 2) + '])'

        # Handle other objects
        s = repr(obj)
        if debug:
            s += f'  # type: {type(obj).__name__} id: {id(obj)}'
        return s

    representation = _pretty(self, 0)
    if indent:
        representation = '\n'.join(indent_str + line for line in representation.splitlines())
    return representation

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner

def get_versions():
    """Get version information or return default if unable to do so."""
    try:
