def register_vcs_handler(vcs, method):  # decorator
    """Create decorator to mark a method as the handler of a VCS."""
    def decorate(f):
        if vcs not in HANDLERS:
            HANDLERS[vcs] = {}
        HANDLERS[vcs][method] = f
        return f
    return decorate

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Helper to recursively walk the hierarchy
    def _walk(obj):
        nonlocal num_objects, good_objects
        # Count this object
        num_objects += 1
        valid = True

        # Validate the object itself if requested
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    valid = obj.validate()
                else:
                    # If no validate method, assume valid
                    valid = True
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"[WARN] Validation error for {obj}: {exc}")

        # Check digest if requested and object passed validation
        if check_digests and valid:
            try:
                if hasattr(obj, 'get_digest') and hasattr(obj, 'expected_digest'):
                    if obj.get_digest() != obj.expected_digest:
                        valid = False
                        if show_warnings:
                            print(f"[WARN] Digest mismatch for {obj}")
                # If digest attributes are missing, skip digest check
            except Exception as exc:
                valid = False
                if show_warnings:
                    print(f"[WARN] Digest check error for {obj}: {exc}")

        if valid:
            good_objects += 1

        # Recurse into children if any
        children = None
        if hasattr(obj, 'children'):
            children = obj.children
        elif isinstance(obj, dict):
            # If the object is a dict, treat its values as potential children
            children = obj.values()
        if children:
            for child in children:
                _walk(child)

    # Start walking from the root(s)
    roots = getattr(self, '_storage_root', None)
    if roots is None:
        # Nothing to validate
        return num_objects, good_objects

    if isinstance(roots, (list, tuple, set)):
        for root in roots:
            _walk(root)
    elif isinstance(roots, dict):
        for root in roots.values():
            _walk(root)
    else:
        # Single root object
        _walk(roots)

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import json

    # Ensure we have a place to record differences
    if not hasattr(self, "different_digests"):
        self.different_digests = {}

    # The base directory that contains all inventories
    if not hasattr(self, "inventory_dir"):
        raise AttributeError("self.inventory_dir must be set to the base inventory directory")

    # Load the root inventory once
    root_inv_path = os.path.join(self.inventory_dir, "inventory.json")
    if not os.path.exists(root_inv_path):
        raise FileNotFoundError(f"Root inventory not found at {root_inv_path}")
    with open(root_inv_path, "r", encoding="utf-8") as f:
        root_inventory = json.load(f)

    # Cumulative inventory that should grow with each version
    cumulative = {}

    for vdir in version_dirs:
        inv_path = os.path.join(self.inventory_dir, vdir, "inventory.json")
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Missing inventory for version {vdir} at {inv_path}")

        with open(inv_path, "r", encoding="utf-8") as f:
            inv = json.load(f)

        # Each inventory must contain all entries from previous versions
        for content in cumulative:
            if content not in inv:
                raise ValueError(
                    f"Inventory for version {vdir} is missing content {content} "
                    f"that existed in earlier versions"
                )

        # Update cumulative inventory and check digest consistency
        for content, digest in inv.items():
            if content in cumulative and digest != cumulative[content]:
                raise ValueError(
                    f"Digest mismatch for {content} in version {vdir}: "
                    f"expected {cumulative[content]}, got {digest}"
                )
            cumulative[content] = digest

        # Record any digests that differ from the root inventory
        for content, digest in inv.items():
            root_digest = root_inventory.get(content)
            if root_digest is None:
                # New content added in this version; nothing to compare
                continue
            if digest != root_digest:
                self.different_digests.setdefault(content, []).append(vdir)

    return self.different_digests

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise ValueError("params must be a dictionary")
    if bug_ids:
        if isinstance(bug_ids, (list, tuple)):
            # Bugzilla expects a comma‑separated string of IDs
            params['ids'] = ','.join(str(b) for b in bug_ids)
        else:
            params['ids'] = str(bug_ids)
    return params

