def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if not dicts:
        return {}
    counters = [Counter(d) for d in dicts]
    return dict(reduce(operator.add, counters))

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    if not url:
        return ''

    if not url_args:
        return url

    for key, value in url_args.items():
        placeholder = '{' + key + '}'
        url = url.replace(placeholder, str(value))
        # also support colon-prefixed placeholders
        colon_placeholder = ':' + key
        url = url.replace(colon_placeholder, str(value))
    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if val is None:
        return True
    if isinstance(val, str):
        stripped = val.strip()
        if not stripped:
            return True
        if stripped.lower() in ('none', 'null', 'undefined'):
            return True
    return False

