def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    return re.sub(r"(^['\"]|['\"]$)", "", name)

def split(s, platform='this'):
    """Multi-platform variant of shlex.split() for command-line splitting.
    For use with subprocess, for argv injection etc. Using fast REGEX.

    platform: 'this' = auto from current platform;
              1 = POSIX;
              0 = Windows/CMD
              (other values reserved)
    """
    import sys
    if platform == 'this':
        platform = 0 if sys.platform.startswith('win') else 1
    if platform == 1:  # POSIX
        pattern = re.compile(r'''(?:"([^"]*)"|'([^']*)'|(\S+))''')
        parts = []
        for m in pattern.finditer(s):
            if m.group(1) is not None:
                parts.append(re.sub(r'\\(.)', r'\1', m.group(1)))
            elif m.group(2) is not None:
                parts.append(re.sub(r'\\(.)', r'\1', m.group(2)))
            else:
                parts.append(m.group(3))
        return parts
    elif platform == 0:  # Windows
        pattern = re.compile(r'''(?:"((?:[^"\\]|\\.)*)"|(\S+))''')
        parts = []
        for m in pattern.finditer(s):
            if m.group(1) is not None:
                quoted = m.group(1)
                parts.append(re.sub(r'\\(.)', r'\1', quoted))
            else:
                parts.append(m.group(2))
        return parts
    else:
        raise ValueError('Unsupported platform value: %r' % platform)

def addignored(ignored):
    """Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""
    cmd = ['git', 'ls-files', '--others', '--ignored', '--exclude-standard']
    try:
        output = subprocess.check_output(cmd, universal_newlines=True)
    except subprocess.CalledProcessError:
        return ''
    files = [f.strip() for f in output.splitlines() if f.strip()]
    files.sort()
    return ','.join(files)

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    freq = frequency.strip()
    if freq.lower() == "always":
        return None
    parts = freq.split()
    if len(parts) < 2:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")
    number_str, unit = parts[0], parts[1].lower()
    try:
        number = int(number_str)
    except ValueError:
        raise ValueError(f"Invalid number in frequency: '{number_str}'")
    unit_map = {
        'day': 'days',
        'days': 'days',
        'hour': 'hours',
        'hours': 'hours',
        'minute': 'minutes',
        'minutes': 'minutes',
        'second': 'seconds',
        'seconds': 'seconds',
        'week': 'weeks',
        'weeks': 'weeks',
    }
    if unit not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: '{unit}'")
    kwargs = {unit_map[unit]: number}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    # Direct string check for common localhost names
    if host.lower() == "localhost":
        return True
    try:
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False
    for info in infos:
        addr = info[4][0]
        # IPv6 loopback
        if ":" in addr:
            if addr == "::1" or addr == "0:0:0:0:0:0:0:1":
                return True
        # IPv4 loopback
        else:
            if addr.startswith("127."):
                return True
    return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    # Git Bash on Windows sets the MSYSTEM environment variable
    # and the OSTYPE variable starts with 'msys'.
    if os.name != 'nt':
        return False
    return 'MSYSTEM' in os.environ or os.environ.get('OSTYPE', '').startswith('msys')

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if pattern is None:
        return None
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)
    # If it's already a compiled regex pattern, return it unchanged
    if hasattr(pattern, "pattern"):
        return pattern
    raise TypeError(f"Invalid pattern type: {type(pattern)}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize commands to a list
    if isinstance(commands, str):
        commands = [commands]
    # Normalize args to a list
    if isinstance(args, str):
        args = [args]
    # If a single args list is provided for multiple commands, broadcast it
    if len(args) == 1 and len(commands) > 1:
        args = args * len(commands)
    outputs = []
    for i, cmd in enumerate(commands):
        # Determine arguments for this command
        cmd_args = args[i] if i < len(args) else []
        if isinstance(cmd_args, str):
            cmd_args = [cmd_args]
        # Build the full command list
        if isinstance(cmd, list):
            full_cmd = cmd + cmd_args
        else:
            full_cmd = [cmd] + cmd_args
        if verbose:
            print("Running command:", " ".join(full_cmd))
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else None,
                text=True,
                check=True
            )
            outputs.append(result.stdout)
        except subprocess.CalledProcessError as e:
            raise RuntimeError(f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}") from e
    return outputs[-1] if outputs else None

def is_ipv4(target):
    """ Test if IPv4 address or not
    """
