def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    mean = 0.2
    sigma = 0.1
    return 1/(sigma*np.sqrt(2*np.pi))*np.exp(-0.5*((x-mean)/sigma)**2)

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os, logging, toml, yaml, json

    def _expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        if isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_expand_env(v) for v in value]
        return value

    config_map = {}
    error_records = []

    for fname in config_filenames:
        if not os.path.exists(fname):
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f'Configuration file not found: {fname}',
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue

        try:
            with open(fname, 'r') as f:
                raw = f.read()
            if fname.lower().endswith('.toml'):
                cfg = toml.loads(raw)
            elif fname.lower().endswith(('.yaml', '.yml')):
                cfg = yaml.safe_load(raw)
            elif fname.lower().endswith('.json'):
                cfg = json.loads(raw)
            else:
                record = logging.LogRecord(
                    name='config_loader',
                    level=logging.ERROR,
                    pathname=fname,
                    lineno=0,
                    msg=f'Unsupported configuration file format: {fname}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                continue

            if resolve_env:
                cfg = _expand_env(cfg)

            if overrides:
                cfg.update(overrides)

            config_map[fname] = cfg

        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f'Error parsing configuration file {fname}: {exc}',
                args=(),
                exc_info=(type(exc), exc, exc.__traceback__)
            )
            error_records.append(record)

    return config_map, error_records

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if no new scale is requested
    if other is None:
        return self.scale

    # Validate the new scale is a numeric scalar
    try:
        new_scale = float(other)
    except Exception:
        raise TypeError("`other` must be a numeric scalar")

    # Ensure the current scale is known and non-zero
    if not hasattr(self, "scale") or self.scale is None:
        raise LenaValueError("Current scale is unknown")
    if not isinstance(self.scale, (int, float, complex)) or self.scale == 0:
        raise LenaValueError("Current scale is zero or non-numeric")

    # Determine the last coordinate field
    if not hasattr(self, "fields") or not self.fields:
        raise LenaValueError("Graph has no fields to rescale")
    last_field = self.fields[-1]

    # Compute scaling factor
    factor = new_scale / self.scale

    # Rescale the data for the last coordinate
    if hasattr(self, "data"):
        if isinstance(self.data, dict):
            if last_field in self.data:
                self.data[last_field] = self.data[last_field] * factor
        elif isinstance(self.data, list):
            self.data[-1] = self.data[-1] * factor

    # Rescale the errors for the last coordinate, if present
    if hasattr(self, "errors") and self.errors is not None:
        if isinstance(self.errors, dict):
            if last_field in self.errors:
                self.errors[last_field] = self.errors[last_field] * factor
        elif isinstance(self.errors, list):
            self.errors[-1] = self.errors[-1] * factor

    # Update the graph's scale
    self.scale = new_scale
    return self.scale

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Check that candidate claims to provide iface (unless tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(
                    f"{candidate!r} does not claim to provide {iface!r}"
                )
        except Exception as exc:
            errors.append(
                f"Error checking providedBy for {candidate!r} and {iface!r}: {exc}"
            )

    # 2. Check that candidate defines all required methods
    for method_name in iface.methods():
        if not hasattr(candidate, method_name):
            errors.append(
                f"{candidate!r} does not define required method {method_name!r}"
            )
            continue
        method = getattr(candidate, method_name)
        if not callable(method):
            errors.append(
                f"{candidate!r} attribute {method_name!r} is not callable"
            )
            continue

        # 3. Check method signature
        try:
            iface_method = iface.getMethod(method_name)
            iface_sig = iface_method.signature
        except Exception:
            iface_sig = None

        try:
            cand_sig = inspect.signature(method)
        except Exception as exc:
            errors.append(
                f"Could not inspect signature of {candidate!r}.{method_name!r}: {exc}"
            )
            continue

        if iface_sig is not None:
            # Compare signatures as strings
            cand_sig_str = str(cand_sig)
            if cand_sig_str != iface_sig:
                errors.append(
                    f"Signature mismatch for {candidate!r}.{method_name!r}: "
                    f"expected {iface_sig!r}, got {cand_sig_str!r}"
                )

    # 4. Check that candidate defines all required attributes
    for attr_name in iface.attributes():
        if not hasattr(candidate, attr_name):
            errors.append(
                f"{candidate!r} does not define required attribute {attr_name!r}"
            )

    # 5. Raise errors if any
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    # Determine the class to inspect
    cls = candidate if isinstance(candidate, type) else candidate.__class__

    # If iface is a class, check subclass relationship
    if isinstance(iface, type):
        if not issubclass(cls, iface):
            raise TypeError(f"{cls.__name__} does not subclass {iface.__name__}")

    # Check that all public attributes/methods defined in iface are present in cls
    for attr in dir(iface):
        if attr.startswith('_'):
            continue
        if not hasattr(cls, attr):
            msg = f"{cls.__name__} is missing attribute {attr} required by {iface.__name__}"
            if tentative:
                import warnings
                warnings.warn(msg)
            else:
                raise AttributeError(msg)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is given, validate it
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"__metaclass__ must be a class, not {type(explicit_mc).__name__}")
        # If no bases, the explicit metaclass is the result
        if not bases:
            return explicit_mc
        # Ensure the explicit metaclass is compatible with all base metaclasses
        for base in bases:
            base_meta = type(base)
            if not issubclass(explicit_mc, base_meta):
                raise TypeError(
                    f"__metaclass__ {explicit_mc.__name__} is not a subclass of {base_meta.__name__}"
                )
        return explicit_mc

    # No explicit metaclass: determine the most derived metaclass from the bases
    if not bases:
        return type

    # Start with the metaclass of the first base
    metaclass = type(bases[0])
    for base in bases[1:]:
        base_meta = type(base)
        if issubclass(base_meta, metaclass):
            metaclass = base_meta
        elif not issubclass(metaclass, base_meta):
            raise TypeError(
                f"metaclass conflict: {metaclass.__name__} and {base_meta.__name__}"
            )
    return metaclass

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._key_map:
        raise KeyError('cache is empty')
    # Identify the least frequently used frequency
    freq = self._min_freq
    # Get an arbitrary key from the OrderedDict of that frequency
    key = next(iter(self._freq_map[freq]))
    # Retrieve the value and its frequency
    value, _ = self._key_map.pop(key)
    # Remove the key from the frequency map
    del self._freq_map[freq][key]
    # If no more keys at this frequency, clean up and update min_freq
    if not self._freq_map[freq]:
        del self._freq_map[freq]
        if self._freq_map:
            self._min_freq = min(self._freq_map)
        else:
            self._min_freq = 0
    return (key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    node = self._tail[2]
    if node is self._head:
        raise KeyError('list is empty')
    self._remove(node)
    return (node[0], node[1])

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    node = self._head[2]
    if node is self._tail:
        raise KeyError('list is empty')
    self._remove(node)
    return (node[0], node[1])

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    return dict.popitem(self)

