def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def format_dt(dt):
    """Format a datetime in the way that D* nodes expect."""
    # Ensure the datetime is timezone‑aware and in UTC
    if dt.tzinfo is None:
        dt = dt.replace(tzinfo=datetime.timezone.utc)
    else:
        dt = dt.astimezone(datetime.timezone.utc)
    # Return ISO‑8601 string with trailing 'Z' to indicate UTC
    return dt.strftime("%Y-%m-%dT%H:%M:%SZ")

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    scheme, netloc, path, query, fragment = urlparse.urlsplit(url)
    if scheme not in ('http', 'https', 'ftp', 'ftps'):
        return None
    req = Request(url, method='HEAD', headers={'Host': netloc})
    try:
        resp = urlopen(req)
        try:
            if hasattr(resp, 'code') and resp.code != 200 and scheme not in ('ftp', 'ftps'):
                return None
            return resp.info().get('content-type')
        finally:
            resp.close()
    except Exception:
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not isinstance(tag, str):
        return False
    if not tag:
        return False
    return all(c.isalnum() or c in '-_' for c in tag)

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        tag = child.tag
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    if not url:
        raise ValueError("url must be provided")
    # Remove any trailing slash from the base url
    base = url.rstrip("/")
    # Default document path if none provided
    if document_path is None:
        document_path = "/nodeinfo/1.0.json"
    # Ensure the document path starts with a slash
    if not document_path.startswith("/"):
        document_path = "/" + document_path
    href = f"{base}{document_path}"
    return {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/1.0",
                "href": href
            }
        ]
    }

def verify_relayable_signature(public_key, doc, signature):
    """
    Verify the signed XML elements to have confidence that the claimed
    author did actually generate this message.
    """
    try:
        # Parse the XML document
        if isinstance(doc, str):
            root = etree.fromstring(doc)
        else:
            root = doc

        # Parse the signature element
        if isinstance(signature, str):
            sig_node = etree.fromstring(signature)
        else:
            sig_node = signature

        # Create a signature context
        ctx = xmlsec.SignatureContext()

        # Load the public key
        if isinstance(public_key, str):
            # Try to load as a file path first
            try:
                key = xmlsec.Key.from_file(public_key, xmlsec.KeyFormat.PEM)
            except Exception:
                # Fallback to loading from memory
                key = xmlsec.Key.from_memory(public_key, xmlsec.KeyFormat.PEM, None)
        else:
            key = public_key

        ctx.key = key

        # Verify the signature
        ctx.verify(sig_node)
        return True
    except Exception:
        return False

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document:
        return None
    # Try JSON first
    try:
        data = json.loads(document)
        result = {}
        result["subject"] = data.get("subject")
        result["aliases"] = data.get("aliases", [])
        links = []
        for link in data.get("links", []):
            l = {}
            for key in ("rel", "href", "type", "template", "title"):
                if key in link:
                    l[key] = link[key]
            links.append(l)
        result["links"] = links
        return result
    except Exception:
        pass

    # Fallback to XRD (XML)
    try:
        root = ET.fromstring(document)
        ns = {"xrd": "http://docs.oasis-open.org/ns/xri/xrd-1.0"}
        subject_el = root.find("xrd:Subject", ns) or root.find("Subject")
        result = {}
        result["subject"] = subject_el.text if subject_el is not None else None
        aliases = []
        for alias_el in root.findall("xrd:Alias", ns) or root.findall("Alias"):
            if alias_el.text:
                aliases.append(alias_el.text)
        result["aliases"] = aliases
        links = []
        for link_el in root.findall("xrd:Link", ns) or root.findall("Link"):
            l = {}
            for attr in ("rel", "href", "type", "template", "title"):
                val = link_el.get(attr)
                if val:
                    l[attr] = val
            links.append(l)
        result["links"] = links
        return result
    except Exception:
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        host = handle.split("@")[1]
    except Exception:
        return None
    resource = urllib.parse.quote(handle)
    url = f"https://{host}/.well-known/webfinger?resource=acct:{resource}"
    try:
        with urllib.request.urlopen(url) as resp:
            return resp.read().decode("utf-8")
    except Exception:
        return None

def retrieve_and_parse_diaspora_webfinger(handle):
    """
    Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        host = handle.split("@")[1]
    except AttributeError:
        logger.warning("retrieve_and_parse_diaspora_webfinger: invalid handle given: %s", handle)
        return None
    document, code, exception = fetch_document(
        host=host, path="/.well-known/webfinger?resource=acct:%s" % quote(handle),
    )
    if document:
        return parse_diaspora_webfinger(document)
    hostmeta = retrieve_diaspora_host_meta(host)
    if not hostmeta:
        return None
    url = hostmeta.find_link(rels="lrdd").template.replace("{uri}", quote(handle))
    document, code, exception = fetch_document(url)
    if exception:
        return None
    return parse_diaspora_webfinger(document)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    file_list = []
    for directory in settings_dirs:
        try:
            for fname in os.listdir(directory):
                if spec_option:
                    if isinstance(spec_option, str):
                        if not fname.endswith(spec_option):
                            continue
                    else:
                        if not re.search(spec_option, fname):
                            continue
                file_list.append(os.path.join(directory, fname))
        except OSError:
            continue
    return sorted(file_list)

