def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content must be provided")
        try:
            data = yaml.safe_load(spec_content)
        except Exception as e:
            raise IRValidatorException(f"Error parsing YAML: {e}")
        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must be a mapping")
        required = getattr(cls, "REQUIRED_FIELDS", [])
        missing = [field for field in required if field not in data]
        if missing:
            raise IRValidatorException(f"Missing required fields: {', '.join(missing)}")
        return data

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _resolve(name, seen):
        if name not in parser_dict:
            raise KeyError(f"Parser '{name}' not found for include.")
        parser = parser_dict[name]
        if 'include' not in parser:
            return parser
        includes = parser['include']
        if isinstance(includes, str):
            includes = [includes]
        merged = {}
        for inc in includes:
            if inc in seen:
                raise RuntimeError(f"Circular include detected: {' -> '.join(list(seen)+[inc])}")
            seen.add(inc)
            inc_parser = _resolve(inc, seen)
            merged.update(inc_parser)
            seen.remove(inc)
        # current parser overrides included ones
        for k, v in parser.items():
            if k != 'include':
                merged[k] = v
        return merged

    for key in list(parser_dict.keys()):
        parser_dict[key] = _resolve(key, set([key]))

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            continue

        # Resolve value from spec if present, otherwise use the option's default
        try:
            val = self.spec[arg.name]
        except Exception:
            val = arg.default

        if val is not NoDefault:
            defaults[arg.name] = val

        # If this is a dict option, recursively resolve defaults for its scheme
        if isinstance(arg, DictOption) and arg.scheme:
            sub_defaults = arg.scheme.get_spec_defaults()
            if sub_defaults:
                defaults[arg.name] = sub_defaults

    return defaults

