    if cmd_spec is None:
        return None
    # Return the specific argument's specification, or None if it doesn't exist
    return cmd_spec.get(argument_name)

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    missing = []
    for name in getattr(self, 'required_args', []):
        if name not in args or args[name] is None:
            missing.append(name)
    if missing:
        raise ValueError(f"Missing required argument(s): {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # support dict or object with attributes
        cond = opt.get('required_when') if isinstance(opt, dict) else getattr(opt, 'required_when', None)
        if cond is None:
            continue
        name = opt.get('name') if isinstance(opt, dict) else getattr(opt, 'name', None)
        if name is None:
            continue
        matched = False
        try:
            if callable(cond):
                matched = bool(cond(args, command_name))
            elif isinstance(cond, dict):
                if command_name in cond:
                    matched = bool(cond[command_name])
            elif isinstance(cond, (list, tuple, set)):
                matched = command_name in cond
            elif isinstance(cond, bool):
                matched = cond
            # other types (e.g., string) are ignored
        except Exception:
            matched = False
        if matched:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Retrieve length constraints from the parsed YAML configuration
    arg_specs = self.parsed_yaml.get('args', {})
    for arg_name, value in args.items():
        # Get the maximum allowed length for this argument, if any
        spec = arg_specs.get(arg_name, {})
        max_len = spec.get('length')
        if max_len is None:
            continue  # No length constraint specified
        if value is None:
            continue  # Nothing to check for a missing value
        try:
            val_len = len(value)
        except TypeError:
            # Value has no length (e.g., an int); skip length check
            continue
        if val_len > max_len:
            raise ValueError(
                f"Argument '{arg_name}' length {val_len} exceeds maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the argument definitions from the parsed YAML
    arg_defs = self.parsed_yaml.get('args', {})
    # Iterate over the provided arguments
    for arg_name, value in args.items():
        # Find the definition for this argument
        if isinstance(arg_defs, dict):
            arg_def = arg_defs.get(arg_name)
        else:  # list of dicts
            arg_def = None
            for item in arg_defs:
                if isinstance(item, dict) and arg_name in item:
                    arg_def = item[arg_name]
                    break
        if not arg_def:
            continue
        # If the argument has a 'choices' list, validate the value
        choices = arg_def.get('choices')
        if choices is None:
            continue
        if value not in choices:
            raise ValueError(
                f"Invalid value for argument '{arg_name}': {value!r}. "
                f"Expected one of: {choices}"
            )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure the instance has min and max attributes
    if not hasattr(self, 'min') or not hasattr(self, 'max'):
        raise AttributeError("Instance must have 'min' and 'max' attributes")
    min_val = self.min
    max_val = self.max
    if min_val is None or max_val is None:
        raise ValueError("min and max values must not be None")

    # Determine the iterable of values to check
    if isinstance(args, dict):
        values = args.values()
    else:
        values = args

    for value in values:
        if value < min_val or value > max_val:
            raise ValueError(f"Argument {value!r} is out of bounds [{min_val}, {max_val}]")
    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Determine the underlying type or parser from the spec_option
    parser = spec_option.get('parser')
    typ = spec_option.get('type', str)

    def _type(value):
        try:
            if parser:
                return parser(value)
            return typ(value)
        except Exception as exc:
            raise ValueError(f"Invalid value for {option_name} in {subcommand}: {exc}")

    _type.__name__ = f"{type_name}_{option_name}_type"
    return _type

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Helper to flatten nested dictionaries into a single level dict
    def _flatten(d, parent_key=''):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key))
            else:
                items[new_key] = v
        return items

    flat_args = _flatten(args)

    # Determine which keys are control arguments.  If the config
    # object provides a list of control keys, use it; otherwise
    # fall back to an empty set.
    control_keys = getattr(self._config, 'control_args', set())

    control_args = {}
    nested_args = {}
    for key, value in flat_args.items():
        if key in control_keys:
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if vars_dict is None:
        vars_dict = {}
    if not extra_vars:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    elif isinstance(extra_vars, list):
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            else:
                raise ValueError("Each extra-var must be a dict")
    else:
        raise ValueError("extra_vars must be a dict or list of dicts")
    return vars_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine the spec file (default to plugin.json)
    spec_file = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_file):
        raise FileNotFoundError(f"Plugin spec file not found: {spec_file}")

    # Load the spec
    with open(spec_file, 'r', encoding='utf-8') as f:
        spec = json.load(f)

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    return _flatten(spec)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    if not os.getenv(env_var):
        os.environ[env_var] = str(self.config_path)
